def compute(vars):
    asset_net_value = vars["v1"]
    total_units_in_份 = vars["v2"]

    if total_units_in_份 == 0:
        return None

    total_units = total_units_in_份 / 1e-8
    unit_net_value = asset_net_value / total_units

    return {
        "value": unit_net_value,
        "trace": {
            "期末基金资产净值": asset_net_value,
            "期末总份额_亿份": total_units_in_份,
            "期末总份额_份": total_units,
            "output_meta": {
                "currency": "CNY",
                "scale": null,
                "unit": "元/份"
            }
        }
    }
